/**
 * Bilingual rendering of messages generated by the analysis (BUY/WAIT/SELL
 * reasons, monthly plan explanations). Safe on client and server.
 */
import type { LineReason, PlanNote } from "@/lib/plan/allocate";
import { timeframeWord } from "@/lib/plain";
import type { Action, Verdict, VerdictReason } from "@/lib/signals/verdict";
import type { Locale } from "./index";

export function actionWord(a: Action, l: Locale) {
  if (l === "fa") return { BUY: "خرید", WAIT: "صبر", SELL: "فروش", NO_DATA: "بدون داده" }[a];
  return { BUY: "BUY", WAIT: "WAIT", SELL: "SELL", NO_DATA: "NO DATA" }[a];
}

function reasonText(r: VerdictReason, l: Locale): string {
  const fa = l === "fa";
  switch (r.k) {
    case "noData":
      return fa ? "هنوز سیگنال قابل‌استفاده‌ای نیست — منتظر بررسی بعدی بمانید یا صفحهٔ وضعیت سیستم را ببینید." : "No usable signals yet — wait for the next scan or check System status.";
    case "sellExits":
      return fa ? `${r.exits} از ${r.total} روشِ ${timeframeWord(r.tf, l)} می‌گویند وقت خروج یا فروش است.` : `${r.exits} of ${r.total} ${timeframeWord(r.tf, l)} strategies show exit or sell conditions.`;
    case "sellDontBuy":
      return fa ? "تا وقتی این وضعیت هست، نخرید." : "Do not buy while these conditions hold.";
    case "buyAgree":
      return fa ? `${r.buys} از ${r.total} روشِ ${timeframeWord(r.tf, l)} فرصت خرید می‌بینند و هیچ‌کدام هشدار نمی‌دهند.` : `${r.buys} of ${r.total} ${timeframeWord(r.tf, l)} strategies see a buy setup and none show a warning.`;
    case "buyRR":
      return fa ? `سود احتمالی حدود ${r.rr.toFixed(1)} برابرِ ضرر احتمالی است (با احتساب کارمزد).` : `Potential gain is about ${r.rr.toFixed(1)}× the potential loss (after fees).`;
    case "buyTimingCalm":
      return fa ? `نمودار ${timeframeWord(r.tf, l)} در حال ریزش نیست.` : `The ${timeframeWord(r.tf, l)} chart is not falling.`;
    case "waitFewBuys":
      return fa ? `فقط ${r.buys} از ${r.total} روشِ ${timeframeWord(r.tf, l)} فرصت خرید می‌بینند (دست‌کم 2 لازم است).` : `Only ${r.buys} of ${r.total} ${timeframeWord(r.tf, l)} strategies see a buy setup (2 needed).`;
    case "waitWarnings":
      return fa ? `${r.exits} روشِ ${timeframeWord(r.tf, l)} هشدار می‌دهد.` : `${r.exits} ${timeframeWord(r.tf, l)} strateg${r.exits === 1 ? "y shows" : "ies show"} a warning.`;
    case "waitLowRR":
      return fa ? `سود احتمالی فقط ${r.rr.toFixed(1)} برابرِ ضرر احتمالی است — دست‌کم ${r.min} برابر لازم است.` : `Potential gain is only ${r.rr.toFixed(1)}× the potential loss — at least ${r.min}× is required.`;
    case "buyConfirmed":
      return fa
        ? `داده‌های صرافی دوم (${r.source}) هم همین فرصت خرید را برای ${r.confirmed} مورد از آن‌ها نشان می‌دهد.`
        : `${r.source}'s data shows the same setup for ${r.confirmed} of them.`;
    case "buyUnchecked":
      return fa ? "این بار امکان بررسی دوباره با داده‌های یک صرافی دیگر نبود." : "Could not double-check on a second exchange this time.";
    case "waitNotConfirmed":
      return fa
        ? `${r.unconfirmed} مورد از ${r.buys} فرصت خرید، در داده‌های صرافی دوم (${r.source}) دیده نمی‌شود — صبر کنید تا تأیید شود.`
        : `${r.unconfirmed} of the ${r.buys} buy setups do not show up on ${r.source}'s data — waiting for confirmation.`;
    case "waitTimingFalling":
      return fa
        ? `تصویر ${timeframeWord(r.tf, l)} مثبت است، ولی نمودار ${timeframeWord(r.tf2, l)} در حال ریزش است (${r.n} هشدار) — صبر کنید آرام شود تا وسط ریزش نخرید.`
        : `The ${timeframeWord(r.tf, l)} picture looks positive, but the ${timeframeWord(r.tf2, l)} chart is falling (${r.n} warnings) — waiting for it to settle avoids buying into a drop.`;
  }
}

export function verdictText(v: Verdict, l: Locale): { headline: string; reasons: string[]; firstReason: string } {
  const fa = l === "fa";
  const headline = {
    noData: fa ? "هنوز دادهٔ کافی نیست" : "Not enough data yet",
    sell: fa ? "سیگنال فروش — اگر دارید، طبق قوانین وقت خروج است" : "Sell signal — if you own it, the rules say exit",
    strongBuy: fa ? "سیگنال خرید قوی" : "Strong buy signal",
    buy: fa ? "سیگنال خرید" : "Buy signal",
    waitAlmost: fa ? "صبر کنید — تقریباً وقت خرید است" : "Wait — almost a buy",
    wait: fa ? "صبر کنید" : "Wait",
  }[v.headlineCode];
  const reasons = v.reasonCodes.map((r) => reasonText(r, l));
  return { headline, reasons, firstReason: v.action === "WAIT" ? (reasons[0] ?? headline) : headline };
}

export function planLineReason(r: LineReason, l: Locale) {
  const fa = l === "fa";
  switch (r.k) {
    case "btc":
      return fa ? "بزرگ‌ترین و قدیمی‌ترین ارز دیجیتال — پایهٔ برنامه، هر ماه خریده می‌شود." : "Biggest and most established crypto — the base of the plan, bought every month.";
    case "eth":
      return fa ? "پایهٔ برنامه — هر ماه خریده می‌شود." : "Base of the plan — bought every month.";
    case "gold":
      return fa ? "طلا آرام‌تر از کریپتو است و ریزش‌های بزرگ را ملایم‌تر می‌کند." : "Gold is calmer than crypto and softens big drops.";
    case "extraBuy":
      return fa ? "سیگنال‌هایش الان «خرید» می‌گویند." : "Its signals say BUY right now.";
    case "extraIdeas":
      return fa ? `${r.n} فرصت خرید روزانه، بدون سیگنال فروش.` : `${r.n} daily buy idea${r.n > 1 ? "s" : ""}, no sell signal.`;
    case "extraNoSell":
      return fa ? "فعلاً سیگنال فروش ندارد." : "No sell signal right now.";
  }
}

export function planNoteText(n: PlanNote, l: Locale) {
  const fa = l === "fa";
  switch (n.k) {
    case "goldMissing":
      return fa ? "طلا (PAXG) در ارزهای شما نیست، برای همین سهمش به بیت‌کوین می‌رسد." : "Gold (PAXG) is not in your coins, so its part goes to Bitcoin.";
    case "skippedSell":
      return fa ? `این ماه کنار گذاشته شدند چون سیگنالشان «فروش» است: ${n.coins.join("، ")}.` : `Skipped this month because their signals say SELL: ${n.coins.join(", ")}.`;
    case "tooSmall":
      return fa ? `مبلغ برای تقسیم بین ارزهای بیشتر کم است (حداقل هر سفارش €${n.min})، برای همین به بیت‌کوین می‌رسد.` : `The amount is too small to split into extra coins (minimum €${n.min} per order), so it goes to Bitcoin.`;
    case "noneGood":
      return fa ? "این ماه هیچ ارز دیگری وضعیت خوبی ندارد، برای همین آن سهم به بیت‌کوین می‌رسد." : "No other coin looks good this month, so that part goes to Bitcoin.";
    case "belowMin":
      return fa ? `${n.coin} کمتر از حداقل سفارش (€${n.min}) می‌شد، برای همین به بیت‌کوین می‌رسد.` : `${n.coin} would be below the minimum order (€${n.min}), so it goes to Bitcoin.`;
  }
}

/** Translate known server/API error messages shown to the user. Unknown messages pass through. */
export function errorText(msg: string, l: Locale) {
  if (l !== "fa") return msg;
  const map: [RegExp, string][] = [
    [/^Invalid email or password\.?$/, "نام کاربری یا رمز عبور اشتباه است."],
    [/^Too many login attempts/, "تعداد تلاش‌های ورود زیاد بود. کمی صبر کنید و دوباره امتحان کنید."],
    [/^Too many requests/, "درخواست‌ها زیاد است. کمی آهسته‌تر."],
    [/^Network error/, "خطای شبکه — دوباره امتحان کنید."],
    [/^You appear to be offline/, "به نظر می‌رسد اینترنت قطع است."],
    [/^Authentication required/, "لطفاً دوباره وارد شوید."],
    [/^Cross-origin request rejected/, "درخواست از آدرس دیگری رد شد. آدرس برنامه را بررسی کنید."],
    [/^The database is unavailable/, "پایگاه داده در دسترس نیست. کمی بعد دوباره امتحان کنید."],
    [/^Internal server error/, "خطای داخلی سرور."],
    [/^Invalid input/, "ورودی نامعتبر است."],
    [/^Enter how much money to put in/, "مبلغ را وارد کنید."],
    [/^Stop must be below the current price/, "حد ضرر باید پایین‌تر از قیمت فعلی باشد."],
    [/^Target must be above the current price/, "هدف سود باید بالاتر از قیمت فعلی باشد."],
    [/^The euro exchange rate is not available yet/, "نرخ یورو هنوز در دسترس نیست. چند دقیقهٔ دیگر امتحان کنید."],
    [/^Unknown asset/, "ارز ناشناخته است."],
    [/^Password is incorrect|^Current password is incorrect/, "رمز عبور اشتباه است."],
    [/^Password must be at least 12 characters/, "رمز عبور باید دست‌کم ۱۲ کاراکتر باشد."],
    [/^Use a mix of letters and numbers/, "از ترکیب حروف و عدد یا نماد استفاده کنید."],
    [/^Watchlist limit/, "به سقف ۲۵ ارز رسیده‌اید."],
    [/^Request failed/, "درخواست ناموفق بود."],
  ];
  for (const [re, fa] of map) if (re.test(msg)) return fa;
  return msg;
}
